using Mentorly.Application.Abstractions.Persistence; using Mentorly.Application.DTOs; using Mentorly.Domain.Entities; using Mentorly.Domain.Enums;
namespace Mentorly.Application.Services;
public interface IQuizService { Task<IReadOnlyList<QuizQuestionDto>> GetQuestionsAsync(Guid activityId,CancellationToken c=default); Task<QuizQuestionDto?> CreateQuestionAsync(Guid activityId,CreateQuizQuestionDto dto,CancellationToken c=default); Task<QuizAttemptDto?> SubmitAsync(Guid enrollmentId,Guid studentId,Guid activityId,SubmitQuizAttemptDto dto,CancellationToken c=default); }
public sealed class QuizService(IQuizRepository quizRepository,IActivityRepository activityRepository,IEnrollmentRepository enrollmentRepository,IGamificationService gamificationService,IUnitOfWork unitOfWork) : IQuizService
{ public async Task<IReadOnlyList<QuizQuestionDto>> GetQuestionsAsync(Guid activityId,CancellationToken c=default)=>(await quizRepository.GetQuestionsAsync(activityId,c)).Select(x=>new QuizQuestionDto(x.Id,x.Prompt,x.OrderIndex)).ToList(); public async Task<QuizQuestionDto?> CreateQuestionAsync(Guid activityId,CreateQuizQuestionDto dto,CancellationToken c=default){var activity=await activityRepository.GetByIdAsync(activityId,c);if(activity is null||activity.Type!=ActivityType.Quiz)return null;var q=new QuizQuestion(Guid.NewGuid(),activityId,dto.Prompt,dto.CorrectAnswer,dto.OrderIndex);quizRepository.AddQuestion(q);await unitOfWork.SaveChangesAsync(c);return new(q.Id,q.Prompt,q.OrderIndex);} public async Task<QuizAttemptDto?> SubmitAsync(Guid enrollmentId,Guid studentId,Guid activityId,SubmitQuizAttemptDto dto,CancellationToken c=default){var enrollment=await enrollmentRepository.GetByIdAsync(enrollmentId,c);var activity=await activityRepository.GetByIdAsync(activityId,c);if(enrollment is null||enrollment.StudentId!=studentId||activity is null||activity.Type!=ActivityType.Quiz)return null;if(!enrollment.CanSubmit(DateTime.UtcNow))throw new InvalidOperationException("Enrollment is inactive.");var questions=await quizRepository.GetQuestionsAsync(activityId,c);if(questions.Count==0)throw new InvalidOperationException("Quiz has no questions.");var correct=questions.Count(q=>dto.Answers.Any(a=>a.QuestionId==q.Id&&string.Equals(a.Answer.Trim(),q.CorrectAnswer,StringComparison.OrdinalIgnoreCase)));var score=Math.Round(correct*100m/questions.Count,2);var passed=score>=70m;var attempt=new QuizAttempt(Guid.NewGuid(),enrollmentId,activityId,score,passed,DateTime.UtcNow);quizRepository.AddAttempt(attempt);await unitOfWork.SaveChangesAsync(c);if(passed)await gamificationService.AwardAsync(studentId,GamificationEventType.ExerciseApproved,attempt.Id,c);return new(attempt.Id,attempt.Score,attempt.Passed,attempt.SubmittedAt);} }
